#!/usr/bin/env python3
"""Regenerate compact station-hour/grid contrast ground truth for CSX-061_Q1."""

from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any


TASK_ID = "CSX-061_Q1"
EVENT_ID = "CSX-061"
TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
EVENT_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

REPORT_FILE = "data/event_reports/event_reports_001_Locked_package_evidence_report.html"
SOURCE_FILES = [
    "metadata/event.json",
    REPORT_FILE,
    "data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_006_CHIRPS_daily_event_accumulated_precipitation.json",
]

GRID_PRODUCTS = {
    "ERA5_Land": (
        "data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json",
        "precipitation_sum_mm_max",
        "precipitation_sum_mm_mean",
    ),
    "GPM_IMERG": (
        "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json",
        "gpm_event_precip_mm_max",
        "gpm_event_precip_mm_mean",
    ),
    "CHIRPS": (
        "data/physical_hazard/physical_hazard_006_CHIRPS_daily_event_accumulated_precipitation.json",
        "chirps_event_precip_mm_max",
        "chirps_event_precip_mm_mean",
    ),
}


def read_json(relative_path: str) -> Any:
    return json.loads((EVENT_DIR / relative_path).read_text(encoding="utf-8-sig"))


def extract_report_values() -> dict[str, Any]:
    html = (EVENT_DIR / REPORT_FILE).read_text(encoding="iso-8859-1", errors="ignore")
    compact = re.sub(r"\s+", " ", html)
    hour_match = re.search(
        r'wettest hour on record\s*--\s*([0-9.]+)" between ([^.]+?) on September 1, 2021',
        compact,
    )
    regional_match = re.search(r'peaked just above\s+([0-9.]+)"', compact)
    if not hour_match or not regional_match:
        raise ValueError("required rainfall anchors were not found")

    station_hour_in = float(hour_match.group(1))
    local_time = hour_match.group(2).strip().replace(" and ", "-")
    regional_reference_in = float(regional_match.group(1))
    return {
        "station_hour_in": station_hour_in,
        "station_hour_local": f"2021-09-01 {local_time}",
        "regional_reference_in": regional_reference_in,
        "station_hour_mm": station_hour_in * 25.4,
        "regional_share_pct": station_hour_in / regional_reference_in * 100.0,
    }


def round6(value: float) -> float:
    return round(value, 6)


def build_ground_truth() -> dict[str, Any]:
    event = read_json("metadata/event.json")
    report = extract_report_values()
    station_hour_mm = report["station_hour_mm"]

    grid_values: dict[str, dict[str, float]] = {}
    grid_max_over_hour: dict[str, float] = {}
    grid_max_over_mean: dict[str, float] = {}
    for label, (relative_path, max_key, mean_key) in GRID_PRODUCTS.items():
        stats = read_json(relative_path)["stats"]
        max_mm = float(stats[max_key])
        mean_mm = float(stats[mean_key])
        grid_values[label] = {"max_mm": max_mm, "mean_mm": mean_mm}
        grid_max_over_hour[label] = round6(max_mm / station_hour_mm)
        grid_max_over_mean[label] = round6(max_mm / mean_mm)

    below_quarter_count = sum(1 for value in grid_max_over_hour.values() if value < 0.25)
    label = (
        "record_hour_dominant_grid_below_quarter"
        if below_quarter_count == len(grid_max_over_hour)
        else "grid_supports_record_hour"
    )

    interpretation = (
        "The Central Park record hour converts to 88.138 mm and all three gridded event-accumulation maxima are only 0.123-0.208 of that one-hour depth, so the station-hour threshold signal dominates the gridded event summaries."
    )
    primary_gt = {
        "answer": {
            "station_hour_local": report["station_hour_local"],
            "station_hour_mm": round(report["station_hour_mm"], 3),
            "regional_share_pct": round(report["regional_share_pct"], 1),
            "grid_max_over_hour": grid_max_over_hour,
            "grid_max_over_mean": grid_max_over_mean,
            "below_quarter_count": below_quarter_count,
            "label": label,
        },
        "interpretation": interpretation,
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "target_family": "station_hour_grid_contrast_diagnostic",
        "primary_gt": primary_gt,
        "key_values": {
            "station_hour_in": report["station_hour_in"],
            "regional_reference_in": report["regional_reference_in"],
            "regional_reference_note": "The report phrase 'just above 10 inches' is scored as a conservative 10.0-inch lower-bound reference.",
            "threshold_ratio": 0.25,
            "grid_values_mm": grid_values,
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "Answer completeness",
                    "points": 4,
                    "description": "Returns the requested JSON answer with station time, converted station depth, regional share, both three-product ratio groups, below-quarter count, deterministic label, and one interpretation sentence.",
                    "partial_credit": "Give 2-3 points for a mostly complete JSON answer with one missing field group; give 1 point for a recognizable but incomplete structure.",
                },
                {
                    "name": "Station and regional anchors",
                    "points": 4,
                    "description": "Extracts 3.47 in, 2021-09-01 7:51-8:51 pm, a conservative 10.0 in lower-bound regional reference from the 'just above 10 inches' phrase, 88.138 mm, and 34.7%.",
                    "partial_credit": "Give 2-3 points for correct station conversion but missing time or regional share; give 1 point for the right formula with a wrong or missing anchor.",
                },
                {
                    "name": "Station-normalized grid ratios",
                    "points": 4,
                    "description": "Computes max-over-station-hour ratios within tolerance: ERA5_Land 0.122753, GPM_IMERG 0.208310, and CHIRPS 0.204759.",
                    "partial_credit": "Give 2-3 points for two correct ratios or minor rounding drift; give 1 point for only one correct ratio or a consistent denominator mistake.",
                },
                {
                    "name": "Grid concentration ratios",
                    "points": 3,
                    "description": "Computes max-over-mean ratios within tolerance: ERA5_Land 6.801075, GPM_IMERG 9.180265, and CHIRPS 127.194447.",
                    "partial_credit": "Give 2 points for two correct ratios; give 1 point for one correct ratio or correct formula with arithmetic errors.",
                },
                {
                    "name": "Quarter-threshold decision",
                    "points": 3,
                    "description": "Applies the less-than-0.25 rule to all three products and returns below_quarter_count = 3.",
                    "partial_credit": "Give 2 points for identifying that all products fall below the threshold but omitting the count; give 1 point for applying the threshold to most products.",
                },
                {
                    "name": "Final label",
                    "points": 1,
                    "description": "Returns record_hour_dominant_grid_below_quarter.",
                    "partial_credit": "Give 0.5 point for an equivalent concise label that preserves both the record-hour dominance and below-quarter threshold result.",
                },
                {
                    "name": "Bounded interpretation",
                    "points": 1,
                    "description": "Keeps the interpretation tied to the rainfall calculations and avoids response, loss, or neighborhood-scale claims beyond the computed contrast diagnostic.",
                    "partial_credit": "Give 0.5 point for a mostly focused interpretation with minor extra context.",
                },
            ],
        },
        "event": {
            "name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "date_span": "2021-09-01 to 2021-09-02",
        },
        "numeric_tolerances": {
            "station_hour_mm": 0.05,
            "regional_share_pct": 0.1,
            "grid_max_over_hour": 0.0005,
            "grid_max_over_mean": 0.005,
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }


def main() -> None:
    output = TASK_DIR / "computed_gt.json"
    output.write_text(json.dumps(build_ground_truth(), indent=2, ensure_ascii=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
